*** Add File: Tests/UITestHelperTests/UITestHelperTests.swift
+import XCTest
+
+final class UITestHelperTests: XCTestCase {
+    private let app = XCUIApplication(bundleIdentifier: "im.vector.app")
+
+    override func setUpWithError() throws {
+        continueAfterFailure = true
+    }
+
+    func testOpenSettingsAndFindAppearance() throws {
+        app.activate()
+        waitForAppToBeReady()
+        saveScreenshot("step-0")
+
+        dismissSystemAlertIfPresent()
+        saveScreenshot("step-1")
+
+        openMainMenu()
+        saveScreenshot("step-2")
+
+        openSettingsIfVisible()
+        saveScreenshot("step-3")
+
+        scrollUntilAppearanceVisible()
+        saveScreenshot("step-4")
+
+        printVisibleLabels()
+    }
+
+    private func waitForAppToBeReady() {
+        let ready = app.staticTexts["All chats"].waitForExistence(timeout: 10)
+        if !ready {
+            _ = app.otherElements.firstMatch.waitForExistence(timeout: 2)
+        }
+    }
+
+    private func dismissSystemAlertIfPresent() {
+        let alert = app.alerts.firstMatch
+        if alert.waitForExistence(timeout: 1) {
+            if alert.buttons["Cancel"].exists {
+                alert.buttons["Cancel"].tap()
+            } else if alert.buttons["Open"].exists {
+                alert.buttons["Open"].tap()
+            }
+        }
+    }
+
+    private func openMainMenu() {
+        let topRight = app.windows.element(boundBy: 0).coordinate(withNormalizedOffset: CGVector(dx: 0.94, dy: 0.09))
+        topRight.tap()
+        _ = app.sheets.firstMatch.waitForExistence(timeout: 2)
+    }
+
+    private func openSettingsIfVisible() {
+        if app.buttons["Settings"].waitForExistence(timeout: 2) {
+            app.buttons["Settings"].tap()
+            return
+        }
+
+        let labels = ["Settings", "Preferences"]
+        for label in labels {
+            let item = app.staticTexts[label]
+            if item.waitForExistence(timeout: 1) {
+                item.tap()
+                return
+            }
+        }
+    }
+
+    private func scrollUntilAppearanceVisible() {
+        let appearance = app.staticTexts["Appearance"]
+        if appearance.exists { return }
+
+        let table = app.tables.firstMatch
+        for _ in 0..<5 {
+            table.swipeUp()
+            if appearance.exists || app.buttons["Appearance"].exists {
+                return
+            }
+        }
+    }
+
+    private func printVisibleLabels() {
+        let labels = app.staticTexts.allElementsBoundByIndex.prefix(40).map { $0.label }
+        print("VISIBLE_STATIC_TEXTS: \(labels)")
+        let buttons = app.buttons.allElementsBoundByIndex.prefix(40).map { $0.label }
+        print("VISIBLE_BUTTONS: \(buttons)")
+    }
+
+    private func saveScreenshot(_ name: String) {
+        let screenshot = XCUIScreen.main.screenshot()
+        let url = URL(fileURLWithPath: "/tmp/\(name).png")
+        try? screenshot.pngRepresentation.write(to: url)
+    }
+}
*** End Patch

